test('selected response capability adds bounded routed-coverage and facility layers to every incident map route',async()=>{
  const facilityKinds=['HOSPITAL','FIRE_STATION','EMS_BASE','CIVIL_PROTECTION','POLICE','SHELTER','WATER_POINT','AIR_SUPPORT_BASE'],candidates=facilityKinds.flatMap((facilityKind,kindIndex)=>Array.from({length:8},(_,rank)=>({facilityKind,kindIndex,rank}))),routeFeatures=candidates.map(({facilityKind,kindIndex,rank},index)=>({type:'Feature',id:`response-route:${index}`,geometry:{type:'LineString',coordinates:[[-8.1,40.1],[-8.09+index/100_000,40.11]]},properties:{layer:'responseCoverageRoutes',facilityId:`facility:${index}`,facilityKind,rank:rank+1,travelTimeMinutes:(rank+1)*5+kindIndex,dispatchClaimed:false}})),facilityFeatures=candidates.map(({facilityKind,kindIndex,rank},index)=>({type:'Feature',id:`response-facility:${index}`,geometry:{type:'Point',coordinates:[-8.09+index/100_000,40.11]},properties:{layer:'responseFacilities',facilityId:`facility:${index}`,facilityKind,rank:rank+1,distanceKm:rank+kindIndex/10,capacityAvailability:'UNKNOWN'}})),projection={resourceCoverageMap:{state:'ROUTED_PATH_COVERAGE_AVAILABLE',generatedAt:'2026-08-25T12:00:00.000Z',routeFeatures:{type:'FeatureCollection',features:routeFeatures},facilityFeatures:{type:'FeatureCollection',features:facilityFeatures},serviceArea:{reason:'Routed paths only.'},truthBoundary:'Routing estimates only; no dispatch or availability is claimed.'}},api=new CanonicalOperatorApiService({services:{...services,responseCapabilityService:{async projectIncident(){return projection;}}},projectRoot:process.cwd()}),screens=[CANONICAL_OPERATOR_SCREENS.INCIDENT_DETAIL,CANONICAL_OPERATOR_SCREENS.INTELLIGENCE_EVIDENCE,CANONICAL_OPERATOR_SCREENS.OPERATIONS],expectedClassCounts=Object.fromEntries(facilityKinds.map(kind=>[kind,3])),classCounts=features=>Object.fromEntries(facilityKinds.map(kind=>[kind,features.filter(feature=>feature.properties.facilityKind===kind).length]));
  for(const screen of screens){const result=await api.project(screen,{incidentId:'incident:one',actor}),scene=result.data.mapScene.value,routes=scene.layers.responseCoverageRoutes,facilities=scene.layers.responseFacilities,encodedBytes=Buffer.byteLength(JSON.stringify(result));assert.equal(result.data.mapScene.state,'READY');assert.ok(scene.layerSet.includes('responseCoverageRoutes'));assert.ok(scene.layerSet.includes('responseFacilities'));assert.ok(scene.legend.includes('responseCoverageRoutes'));assert.ok(scene.legend.includes('responseFacilities'));assert.equal(scene.layerSet.filter(name=>name==='responseCoverageRoutes').length,1);assert.equal(routes.authority,'ROUTING_ESTIMATE');assert.equal(routes.value.length,24);assert.deepEqual(routes.inventory,{returned:24,total:64,truncated:true});assert.deepEqual([...new Set(routes.value.map(feature=>feature.properties.facilityKind))].sort(),[...facilityKinds].sort(),'every routed facility class must survive the cap');assert.deepEqual(classCounts(routes.value),expectedClassCounts,'routed coverage must retain three ranked candidates per facility class');assert.equal(routes.truthBoundary,projection.resourceCoverageMap.truthBoundary);assert.equal(facilities.authority,'GOVERNED_STATIC_CONTEXT');assert.equal(facilities.value.length,24);assert.deepEqual(facilities.inventory,{returned:24,total:64,truncated:true});assert.deepEqual([...new Set(facilities.value.map(feature=>feature.properties.facilityKind))].sort(),[...facilityKinds].sort(),'every mapped facility class must survive the cap');assert.deepEqual(classCounts(facilities.value),expectedClassCounts,'facility points must retain three ranked candidates per facility class');assert.equal(scene.renderedFeatureSet.responseCoverageRoutes,24);assert.equal(scene.renderedFeatureSet.responseFacilities,24);assert.ok(encodedBytes<500_000,`response-capability route DTO was ${encodedBytes} bytes`);}
});
